from itertools import islice

class seekable_original:
    def __init__(self, iterable, maxlen=None):
        self._source = iter(iterable)
        if maxlen is None:
            self._cache = []
        else:
            self._cache = deque([], maxlen)
        self._index = None

    def __next__(self):
        if self._index is not None:
            try:
                item = self._cache[self._index]
            except IndexError:
                self._index = None
            else:
                self._index += 1
                return item

        item = next(self._source)
        self._cache.append(item)
        return item

    def seek(self, index):
        self._index = index
        remainder = index - len(self._cache)
        if remainder > 0:
            consume(self, remainder)

it = seekable_original((str(n) for n in range(10)))
print(f'next(it): {next(it)}')
print(f'next(it): {next(it)}')
print(f'next(it): {next(it)}')
print(f'cache={it._cache}, _index={it._index}')

